import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,DataTable} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {OrganizationLinks} from './organizations.jsx';
import {usePaged,ListState} from './forms.jsx';
const empty={actorId:'',entityType:'',entityId:'',action:'',projectId:'',from:'',to:''};
export function SecurityAudit({params,api}) {
  const orgId=params.orgId;
  const [draft,setDraft]=useState(empty),[filters,setFilters]=useState(empty),[selected,setSelected]=useState(null);
  const path=(orgId?'/orgs/'+orgId+'/audit':'/me/audit')+'?'+queryString(filters);
  const page=usePaged(api,path);
  const update=key=>e=>setDraft({...draft,[key]:e.target.value});
  return <Page title={orgId?'Organization security audit':'Your account security audit'}>
    {orgId?<OrganizationLinks id={orgId}/>:<nav className="subnav"><a href="#/account/security">Account security</a></nav>}
    <p>Security changes persist with actor, target, time and sanitized summaries. Credentials and password hashes are excluded.</p>
    <form onSubmit={e=>{e.preventDefault();setFilters({...draft});page.reset();}}>
      <Field label="Actor id" value={draft.actorId} onInput={update('actorId')} error={page.error?.details?.actorId}/>
      <Field label="Entity type" error={page.error?.details?.entityType}><select value={draft.entityType} onChange={update('entityType')}>
        {['','user','session','api_token','invitation','organization','team','project'].map(type=><option value={type}>{type||'All types'}</option>)}
      </select></Field>
      <Field label="Entity id" value={draft.entityId} onInput={update('entityId')}/>
      <Field label="Action" value={draft.action} onInput={update('action')} placeholder="created, revoked, password_changed…"/>
      {orgId&&<Field label="Project id" value={draft.projectId} onInput={update('projectId')} error={page.error?.details?.projectId}/>}
      <Field label="From, ISO date/time" value={draft.from} onInput={update('from')} placeholder="2026-10-16T00:00:00Z" error={page.error?.details?.from}/>
      <Field label="To, ISO date/time" value={draft.to} onInput={update('to')} error={page.error?.details?.to}/>
      <Button>Apply filters</Button><Button type="button" onClick={()=>{setDraft(empty);setFilters(empty);page.reset();}}>Clear filters</Button>
    </form>
    <ListState page={page}><DataTable items={page.items} empty="No security events match these filters." columns={[
      {key:'time',label:'Time'},{key:'actorId',label:'Actor'},{key:'entityType',label:'Type'},
      {key:'entityId',label:'Target'},{key:'action',label:'Action'},
      {key:'details',label:'Summary',render:item=><Button onClick={()=>setSelected(item)}>View changes</Button>}
    ]}/></ListState>
    {selected&&<section aria-label="Audit event details"><h2>{selected.entityType} · {selected.action}</h2>
      <p>{selected.time} · actor {selected.actorId??'System'}</p>
      <h3>Before</h3><pre>{JSON.stringify(selected.before,null,2)}</pre><h3>After</h3><pre>{JSON.stringify(selected.after,null,2)}</pre>
      <Button onClick={()=>setSelected(null)}>Close details</Button>
    </section>}
  </Page>;
}

import {h} from 'preact';
import {useEffect,useState} from 'preact/hooks';
import {Button,Notice,Loading,useLoad} from '../../components/ui.jsx';
export function useAction(after) {
  const [busy,setBusy]=useState(false),[error,setError]=useState(null),[message,setMessage]=useState('');
  async function run(fn,success='Saved.') {
    setBusy(true);setError(null);setMessage('');
    try {const result=await fn();setMessage(success);after?.(result);return result;}
    catch(error){setError(error);return null;}
    finally{setBusy(false);}
  }
  return {busy,error,message,run,clear:()=>{setError(null);setMessage('');}};
}
export function ActionNotice({action}) {return <><Notice error={action.error}/>{action.error?.details&&<ul role="alert">{Object.entries(action.error.details).map(([key,value])=><li>{key}: {String(value)}</li>)}</ul>}<Notice>{action.message}</Notice></>;}
export function PageButtons({page}) {
  return <nav aria-label="List pages" className="subnav">
    <Button type="button" disabled={!page.hasBack||page.loading} onClick={page.back}>Previous page</Button>
    <span>Page {page.number}</span>
    <Button type="button" disabled={!page.nextCursor||page.loading} onClick={page.next}>Next page</Button>
  </nav>;
}
export function usePaged(api,path,limit=25) {
  const [history,setHistory]=useState([null]);
  useEffect(()=>setHistory([null]),[path]);
  const cursor=history.at(-1);
  const result=useLoad(()=>api.get(path+(path.includes('?')?'&':'?')+'limit='+limit+(cursor?'&cursor='+encodeURIComponent(cursor):'')),[path,cursor]);
  return {...result,items:result.data?.items??[],nextCursor:result.data?.nextCursor,number:history.length,
    hasBack:history.length>1,next:()=>result.data?.nextCursor&&setHistory([...history,result.data.nextCursor]),
    back:()=>setHistory(history.slice(0,-1)),reset:()=>setHistory([null])};
}
export function ListState({page,children}) {
  return <><Notice error={page.error}/>{page.loading?<Loading/>:<>{children}<PageButtons page={page}/></>}</>;
}

import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton,useLoad} from '../../components/ui.jsx';
import {OrganizationLinks} from './organizations.jsx';
import {canManage,roleOptions} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function Members({params,api,store}) {
  const id=params.orgId;
  const organization=useLoad(()=>api.get('/orgs/'+id),[id]);
  const page=usePaged(api,'/orgs/'+id+'/members');
  const org=organization.data?.organization;
  const [name,setName]=useState('');
  const [values,setValues]=useState({userId:'',role:'member'});
  const action=useAction(()=>{page.reload();organization.reload();});
  useEffect(()=>{if(org)setName(org.name);},[org?.id,org?.name]);
  async function rename(event) {
    event.preventDefault();
    await action.run(async()=>{const result=await api.patch('/orgs/'+id,{name});store.set({organization:result.organization});return result;},'Organization renamed.');
  }
  async function add(event) {
    event.preventDefault();const result=await action.run(()=>api.post('/orgs/'+id+'/members',values),'Member added.');
    if(result)setValues({...values,userId:''});
  }
  const editable=member=>canManage(org?.role)&&(member.role!=='owner'||org?.role==='owner');
  async function changeRole(member,role) {
    if(member.role===role)return;
    if(!globalThis.confirm(`Change ${member.name} from ${member.role} to ${role}?`))return;
    await action.run(()=>api.patch('/orgs/'+id+'/members/'+member.userId,{role}),'Role updated.');
  }
  return <Page title={(org?.name??'Organization')+' · Members'}>
    <OrganizationLinks id={id}/><Notice error={organization.error}/><ActionNotice action={action}/>
    <p>Your role: <strong>{org?.role??'Loading'}</strong>. Only owners manage other owners. Every organization must retain an owner.</p>
    <ListState page={page}><DataTable items={page.items} keyField="userId" columns={[
      {key:'name',label:'Name'},{key:'email',label:'Email'},
      {key:'role',label:'Role',render:member=>editable(member)?<select aria-label={'Role for '+member.name} disabled={action.busy} value={member.role} onChange={e=>changeRole(member,e.target.value)}>
        {roleOptions(org.role).map(role=><option value={role}>{role}</option>)}
      </select>:member.role},
      {key:'remove',label:'Membership',render:member=>editable(member)&&<ConfirmButton busy={action.busy}
        message={`Remove ${member.name} from this organization, its teams and granted projects?`}
        onConfirm={()=>action.run(()=>api.delete('/orgs/'+id+'/members/'+member.userId),'Membership removed.')}>Remove</ConfirmButton>}
    ]}/></ListState>
    {canManage(org?.role)&&<>
      <h2>Add an existing account</h2><p>For new colleagues, use <a href={'#/orgs/'+id+'/invitations'}>Invitations</a>.</p>
      <form onSubmit={add}>
        <Field label="User id" required value={values.userId} onInput={e=>setValues({...values,userId:e.target.value})} error={action.error?.details?.userId}/>
        <Field label="Role" error={action.error?.details?.role}><select value={values.role} onChange={e=>setValues({...values,role:e.target.value})}>
          {roleOptions(org.role).map(role=><option>{role}</option>)}
        </select></Field><Button busy={action.busy}>Add member</Button>
      </form><h2>Rename organization</h2><form onSubmit={rename}>
        <Field label="Organization name" required maxLength={120} value={name} onInput={e=>setName(e.target.value)} error={action.error?.details?.name}/>
        <Button busy={action.busy}>Save name</Button>
      </form>
    </>}
  </Page>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {Page,Field,Button,DataTable} from '../../components/ui.jsx';
import {organizationPath} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export {Members} from './members.jsx';
export {Teams,TeamDetail} from './teams.jsx';
export function OrganizationLinks({id}) {
  return <nav className="subnav" aria-label="Organization settings">
    {['members','teams','invitations','audit'].map(tab=><a href={'#'+organizationPath(id,tab)}>{tab}</a>)}
  </nav>;
}
export function Organizations({api,store,navigate}) {
  const page=usePaged(api,'/orgs');
  const [name,setName]=useState('');
  const action=useAction(result=>{store.set({organization:result.organization});navigate(organizationPath(result.organization.id));});
  async function create(event) {event.preventDefault();await action.run(()=>api.post('/orgs',{name}),'Organization created.');}
  return <Page title="Organizations">
    <p>Choose the organization whose projects and people you want to manage.</p>
    <ActionNotice action={action}/>
    <ListState page={page}><DataTable items={page.items} empty="You have no organizations yet. Create one below." columns={[
      {key:'name',label:'Organization',render:org=><a href={'#'+organizationPath(org.id)} onClick={()=>store.set({organization:org})}>{org.name}</a>},
      {key:'role',label:'Your role'}
    ]}/></ListState>
    <h2>Create organization</h2><form onSubmit={create}>
      <Field label="Organization name" value={name} required maxLength={120} onInput={e=>setName(e.target.value)} error={action.error?.details?.name}/>
      <Button busy={action.busy}>Create organization</Button>
    </form>
  </Page>;
}

import {PersonalTokens} from './tokens.jsx';
import {SecurityAudit} from './audit.jsx';
import {Invitations,AcceptInvitation,Outbox} from './invitations.jsx';
import {AccountSecurity,ResetPassword} from './account.jsx';
import {Organizations,Members,Teams,TeamDetail} from './organizations.jsx';
export const routes=[{path:'/account/tokens',component:PersonalTokens},{path:'/account/audit',component:SecurityAudit},{path:'/orgs/:orgId/audit',component:SecurityAudit},{path:'/orgs/:orgId/invitations',component:Invitations},{path:'/orgs/:orgId/outbox',component:Outbox},{path:'/invitations/accept',component:AcceptInvitation},{path:'/account/security',component:AccountSecurity},{path:'/account/outbox',component:Outbox},{path:'/reset',component:ResetPassword},{path:'/orgs',component:Organizations},{path:'/orgs/:orgId/members',component:Members},{path:'/orgs/:orgId/teams',component:Teams},{path:'/teams/:teamId',component:TeamDetail}];
export const navigation=[{path:'/orgs',label:'Organizations'},{path:'/account/security',label:'Account security'}];

import {h} from 'preact';
import {useState,useEffect} from 'preact/hooks';
import {Page,Field,Button,Notice,DataTable,ConfirmButton,Loading,useLoad} from '../../components/ui.jsx';
import {OrganizationLinks} from './organizations.jsx';
import {canManage,organizationPath} from './state.js';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
export function Teams({params,api}) {
  const id=params.orgId;
  const organization=useLoad(()=>api.get('/orgs/'+id),[id]);
  const page=usePaged(api,'/orgs/'+id+'/teams');
  const [values,setValues]=useState({name:'',description:''});
  const action=useAction(()=>{page.reset();page.reload();});
  async function create(event) {
    event.preventDefault();const result=await action.run(()=>api.post('/orgs/'+id+'/teams',values),'Team created.');
    if(result)setValues({name:'',description:''});
  }
  const org=organization.data?.organization;
  return <Page title={(org?.name??'Organization')+' · Teams'}>
    <OrganizationLinks id={id}/><Notice error={organization.error}/><ActionNotice action={action}/>
    <ListState page={page}><DataTable items={page.items} empty="No teams yet." columns={[
      {key:'name',label:'Team',render:team=><a href={'#/teams/'+team.id}>{team.name}</a>},{key:'description',label:'Description'}
    ]}/></ListState>
    {canManage(org?.role)&&<><h2>Create team</h2><form onSubmit={create}>
      <Field label="Team name" required maxLength={120} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
      <Field label="Description" error={action.error?.details?.description}><textarea value={values.description} maxLength={2000} onInput={e=>setValues({...values,description:e.target.value})}/></Field>
      <Button busy={action.busy}>Create team</Button>
    </form></>}
  </Page>;
}
export function TeamDetail({params,api,navigate}) {
  const id=params.teamId;
  const detail=useLoad(async()=>{const team=(await api.get('/teams/'+id)).team;const org=(await api.get('/orgs/'+team.orgId)).organization;return{team,org};},[id]);
  const members=usePaged(api,'/teams/'+id+'/members');
  const team=detail.data?.team,org=detail.data?.org;
  const [values,setValues]=useState({name:'',description:''});
  const [userId,setUserId]=useState('');
  const action=useAction(()=>{members.reload();detail.reload();});
  useEffect(()=>{if(team)setValues({name:team.name,description:team.description});},[team?.id,team?.name,team?.description]);
  const manage=canManage(org?.role);
  return <Page title={team?.name??'Team'}>
    <Notice error={detail.error}/><ActionNotice action={action}/>
    {detail.loading?<Loading/>:team&&<>
      <OrganizationLinks id={team.orgId}/><p>{team.description||'No description.'}</p>
      <ListState page={members}><DataTable items={members.items} keyField="userId" empty="This team has no members." columns={[
        {key:'name',label:'Member'},{key:'email',label:'Email'},{key:'role',label:'Organization role'},
        {key:'remove',label:'Actions',render:member=>manage&&<ConfirmButton busy={action.busy} message={'Remove '+member.name+' from this team? Organization membership is retained.'}
          onConfirm={()=>action.run(()=>api.delete('/teams/'+id+'/members/'+member.userId),'Team membership removed.')}>Remove</ConfirmButton>}
      ]}/></ListState>
      {manage&&<>
        <h2>Add organization member</h2><p>Browse the organization roster below to choose an account.</p>
        <MemberPicker api={api} orgId={team.orgId} value={userId} onChoose={setUserId}/>
        <form onSubmit={e=>{e.preventDefault();action.run(()=>api.post('/teams/'+id+'/members',{userId}),'Member added to team.');}}>
          <Field label="Selected member id" required value={userId} onInput={e=>setUserId(e.target.value)} error={action.error?.details?.userId}/>
          <Button busy={action.busy} disabled={!userId}>Add to team</Button>
        </form><h2>Edit team</h2><form onSubmit={e=>{e.preventDefault();action.run(()=>api.patch('/teams/'+id,values),'Team saved.');}}>
          <Field label="Name" required maxLength={120} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
          <Field label="Description" error={action.error?.details?.description}><textarea value={values.description} maxLength={2000} onInput={e=>setValues({...values,description:e.target.value})}/></Field>
          <Button busy={action.busy}>Save team</Button>
        </form><h2>Delete team</h2><p>Deleting a team removes its roster. Organization memberships are retained.</p>
        <ConfirmButton busy={action.busy} message={'Delete team '+team.name+' and its roster?'} onConfirm={()=>action.run(async()=>{await api.delete('/teams/'+id);navigate(organizationPath(team.orgId,'teams'));},'Team deleted.')}>Delete team</ConfirmButton>
      </>}
    </>}
  </Page>;
}
function MemberPicker({api,orgId,value,onChoose}) {
  const page=usePaged(api,'/orgs/'+orgId+'/members',10);
  return <ListState page={page}><DataTable items={page.items} keyField="userId" columns={[
    {key:'name',label:'Name'},{key:'email',label:'Email'},
    {key:'select',label:'Choose',render:member=><Button type="button" disabled={member.userId===value} onClick={()=>onChoose(member.userId)}>{member.userId===value?'Selected':'Choose'}</Button>}
  ]}/></ListState>;
}

import {h} from 'preact';
import {useState} from 'preact/hooks';
import {PERMISSIONS} from '@crew/shared';
import {Page,Field,Button,Notice,DataTable,ConfirmButton} from '../../components/ui.jsx';
import {usePaged,ListState,useAction,ActionNotice} from './forms.jsx';
import {tokenInput} from '@crew/shared';
export function PersonalTokens({api}) {
  const [filter,setFilter]=useState('all');
  const page=usePaged(api,'/tokens?state='+filter);
  const [values,setValues]=useState({name:'',scopes:['self:read','org:read','project:read','insight:read'],expiresInDays:'30'});
  const [secret,setSecret]=useState(null);
  const action=useAction(()=>{page.reset();page.reload();});
  async function create(event) {
    event.preventDefault();
    const result=await action.run(()=>api.post('/tokens',tokenInput({...values,expiresInDays:values.expiresInDays===''?null:values.expiresInDays})),'Token created. Copy its credential now.');
    if(result){setSecret(result.token);setValues({...values,name:''});}
  }
  function toggle(scope) {setValues({...values,scopes:values.scopes.includes(scope)?values.scopes.filter(item=>item!==scope):[...values.scopes,scope]});}
  return <Page title="Personal API tokens">
    <nav className="subnav"><a href="#/account/security">Account security</a><a href="#/account/audit">Your security audit</a></nav>
    <p>Use tokens with the CLI. Scopes limit API operations; your role and project grants still apply. Revocation is immediate.</p>
    <ActionNotice action={action}/>
    {secret&&<section aria-label="New API credential"><h2>Copy your token</h2><Notice>This credential is displayed once. Store it privately before leaving this page.</Notice>
      <Field label="New token credential"><textarea readOnly value={secret} onFocus={e=>e.target.select()}/></Field>
      <Button onClick={()=>setSecret(null)}>I have saved it; hide token</Button>
    </section>}
    <Field label="Token state"><select value={filter} onChange={e=>setFilter(e.target.value)}>{['all','active','expired','revoked'].map(value=><option>{value}</option>)}</select></Field>
    <ListState page={page}><DataTable items={page.items} empty="No personal API tokens." columns={[
      {key:'name',label:'Name'},{key:'scopes',label:'Scopes',render:item=>item.scopes.join(', ')},{key:'state',label:'State'},
      {key:'expiresAt',label:'Expires',render:item=>item.expiresAt??'No expiry'},{key:'lastUsedAt',label:'Last used'},
      {key:'revoke',label:'Action',render:item=>item.state!=='revoked'&&<ConfirmButton busy={action.busy} message={'Revoke token '+item.name+'? Applications using it will stop authenticating.'}
        onConfirm={()=>action.run(()=>api.delete('/tokens/'+item.id),'Token revoked.')}>Revoke</ConfirmButton>}
    ]}/></ListState>
    <h2>Create personal token</h2><form onSubmit={create}>
      <Field label="Token name" required maxLength={100} value={values.name} onInput={e=>setValues({...values,name:e.target.value})} error={action.error?.details?.name}/>
      <Field label="Expires in days; leave blank for no expiry" type="number" min="1" max="365" value={values.expiresInDays} onInput={e=>setValues({...values,expiresInDays:e.target.value})} error={action.error?.details?.expiresInDays}/>
      <fieldset><legend>Allowed operations</legend><p>Choose the smallest set needed. A global wildcard authorizes every operation your account may perform.</p>
        {['*',...PERMISSIONS].map(scope=><label className="field"><span><input type="checkbox" checked={values.scopes.includes(scope)} onChange={()=>toggle(scope)}/> {scope}</span></label>)}
        {action.error?.details?.scopes&&<Notice error={action.error.details.scopes}/>}
      </fieldset><Button busy={action.busy}>Create token</Button>
    </form>
  </Page>;
}
